-- BEGIN 202610310004_operations.sql
create function public.admin_write(resource text, record_id uuid, payload jsonb, operation text default 'PATCH') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare tbl text; perm text; cols text; vals text; assignments text; result jsonb; clean jsonb; k text; item jsonb; vid uuid;
begin
 tbl=case resource when 'categories' then 'product_categories' when 'collections' then 'product_collections'
 when 'products' then 'products' when 'images' then 'product_images' when 'variants' then 'product_variants'
 when 'coupons' then 'coupons' when 'discounts' then 'discounts' when 'delivery-zones' then 'shipping_zones'
 when 'shipping-rates' then 'shipping_rates' when 'homepage-sections' then 'homepage_sections' when 'banners' then 'banners'
 when 'messages' then 'contact_messages' when 'reviews' then 'product_reviews' when 'customers' then 'profiles'
 when 'sizes' then 'product_sizes' when 'colours' then 'product_colours' end;
 if tbl is null then raise exception 'Unknown management resource'; end if;
 perm=case when tbl in ('product_categories','product_collections','products','product_images','product_variants','product_sizes','product_colours') then
 case when operation='DELETE' then 'DELETE_PRODUCTS' when operation='POST' and tbl='products' then 'CREATE_PRODUCTS' else 'EDIT_PRODUCTS' end
 when tbl in ('coupons','discounts') then 'MANAGE_PROMOTIONS'
 when tbl in ('shipping_zones','shipping_rates') then 'MANAGE_SETTINGS'
 when tbl in ('homepage_sections','banners') then 'MANAGE_WEBSITE'
 when tbl='contact_messages' then 'VIEW_CUSTOMERS' when tbl='profiles' then 'MANAGE_CUSTOMERS' else 'EDIT_PRODUCTS' end;
 perform private.require_permission(perm);
 if operation not in ('POST','PATCH','DELETE') then raise exception 'Unsupported operation'; end if;
 if operation='DELETE' then
  if tbl='products' then update public.products set "isActive"=false,"archivedAt"=now() where id=record_id returning to_jsonb(products.*) into result;
  elsif tbl in ('product_categories','product_collections','shipping_zones','coupons','homepage_sections','banners','discounts') then
   execute format('update public.%I set "isActive"=false where id=$1 returning to_jsonb(%I.*)',tbl,tbl) into result using record_id;
  elsif tbl='contact_messages' then update public.contact_messages set status='ARCHIVED' where id=record_id returning to_jsonb(contact_messages.*) into result;
  elsif tbl in ('product_images','product_reviews') then execute format('delete from public.%I where id=$1 returning to_jsonb(%I.*)',tbl,tbl) into result using record_id;
  else raise exception 'Archive this record instead'; end if;
 else
  clean=payload - array['id','createdAt','updatedAt','archivedAt','soldCount','variants','collectionIds','quantity'];
  if tbl in ('products','product_categories','product_collections') and clean ? 'name' then
   clean=clean||jsonb_build_object('slug',trim(both '-' from regexp_replace(lower(clean->>'name'),'[^a-z0-9]+','-','g'))||case when tbl='products' then '-'||left(coalesce(record_id,gen_random_uuid())::text,8) else '' end);
  end if;
  if tbl in ('products','product_variants') and coalesce(clean->>'sku','')='' then clean=clean||jsonb_build_object('sku','NBL-'||gen_random_uuid()::text); end if;
  if tbl='coupons' and clean ? 'code' then clean=clean||jsonb_build_object('code',upper(clean->>'code')); end if;
  if tbl='profiles' then
   if exists(select 1 from public.admin_roles where "userId"=record_id) then raise exception 'Manage staff in permissions'; end if;
   clean=jsonb_build_object('isActive',(payload->>'isActive')::boolean);
  end if;
  if tbl='product_reviews' then clean=jsonb_build_object('isApproved',(payload->>'isApproved')::boolean); end if;
  if tbl='contact_messages' then clean=payload-array['name','email','subject','message','id','createdAt','updatedAt']; end if;
  if tbl='product_variants' and operation='PATCH' then clean=clean-'productId'; end if;
  if tbl='product_images' and operation='PATCH' then clean=clean-array['productId','path','url']; end if;
  select string_agg(format('%I',c.column_name),','), string_agg(format('(jsonb_populate_record(null::public.%I,$1)).%I',tbl,c.column_name),','),
   string_agg(format('%I=(jsonb_populate_record(null::public.%I,$1)).%I',c.column_name,tbl,c.column_name),',')
   into cols,vals,assignments from information_schema.columns c where c.table_schema='public' and c.table_name=tbl and clean ? c.column_name;
  if cols is null then raise exception 'No editable fields'; end if;
  if operation='POST' then
   execute format('insert into public.%I (%s) select %s returning to_jsonb(%I.*)',tbl,cols,vals,tbl) into result using clean;
  else
   execute format('update public.%I set %s where id=$2 returning to_jsonb(%I.*)',tbl,assignments,tbl) into result using clean,record_id;
  end if;
  if tbl='products' and result is not null then
   if payload ? 'collectionIds' then
    delete from public.product_collection_links where "productId"=(result->>'id')::uuid;
    insert into public.product_collection_links("productId","collectionId") select (result->>'id')::uuid,value::uuid from jsonb_array_elements_text(payload->'collectionIds');
   end if;
   if operation='POST' then
    for item in select value from jsonb_array_elements(coalesce(payload->'variants','[]')) loop
     insert into public.product_variants("productId",sku,size,color,"priceDiff") values((result->>'id')::uuid,coalesce(nullif(item->>'sku',''),'NBL-'||gen_random_uuid()::text),item->>'size',item->>'color',coalesce((item->>'priceDiff')::numeric,0)) returning id into vid;
     insert into public.inventory("variantId",quantity,"lowStockThreshold") values(vid,coalesce((item->>'quantity')::integer,0),coalesce((select (values->>'lowStockThreshold')::integer from public.store_settings where section='products'),5));
     insert into public.inventory_movements("variantId",delta,type,reason,"actorId") values(vid,coalesce((item->>'quantity')::integer,0),'RESTOCK','Initial stock',auth.uid());
    end loop;
   end if;
  elsif tbl='product_variants' and operation='POST' then
   insert into public.inventory("variantId",quantity,"lowStockThreshold") values((result->>'id')::uuid,coalesce((payload->>'quantity')::integer,0),coalesce((select (values->>'lowStockThreshold')::integer from public.store_settings where section='products'),5));
   insert into public.inventory_movements("variantId",delta,type,reason,"actorId") values((result->>'id')::uuid,coalesce((payload->>'quantity')::integer,0),'RESTOCK','Initial stock',auth.uid());
  end if;
 end if;
 if result is null then raise exception 'Record not found' using errcode='P0002'; end if;
 insert into public.activity_logs("adminId",action,entity,"entityId") values(auth.uid(),operation,tbl,result->>'id');
 return result;
end; $$;

create function public.adjust_inventory(variant_id uuid, new_quantity integer, note text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare old public.inventory; result jsonb;
begin
 perform private.require_permission('MANAGE_INVENTORY');
 if length(trim(note))<1 then raise exception 'A stock adjustment reason is required'; end if;
 select * into strict old from public.inventory where "variantId"=variant_id for update;
 if new_quantity<old.reserved then raise exception 'Quantity cannot be less than reserved stock'; end if;
 update public.inventory set quantity=new_quantity where "variantId"=variant_id returning to_jsonb(inventory.*) into result;
 insert into public.inventory_movements("variantId",delta,type,reason,"actorId") values(variant_id,new_quantity-old.quantity,'ADJUSTMENT',note,auth.uid());
 return result;
end; $$;

create function public.save_content(content_slug text, content_data jsonb) returns jsonb language plpgsql security definer set search_path = '' as $$
begin
 perform private.require_permission('MANAGE_WEBSITE');
 if content_slug not in ('homepage','about','contact') then raise exception 'Unknown content section'; end if;
 insert into public.website_settings(slug,data) values(content_slug,content_data) on conflict(slug) do update set data=excluded.data;
 if content_slug='homepage' and content_data ? 'featuredProductIds' then
  delete from public.featured_products;
  insert into public.featured_products("productId","sortOrder") select value::uuid,ordinality::integer from jsonb_array_elements_text(content_data->'featuredProductIds') with ordinality;
 end if;
 return content_data;
end; $$;

create function public.save_settings(setting_section text, setting_values jsonb, expected_version integer) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare result jsonb; item jsonb; role_name text; permission_name text; old public.store_settings;
begin
 if setting_section='permissions' then
  if not public.has_permission('MANAGE_STAFF') or not exists(select 1 from public.admin_roles where "userId"=auth.uid() and role='SUPER_ADMIN' and "isActive") then raise exception 'Super Admin required' using errcode='42501'; end if;
  delete from public.staff_permissions;
  for role_name,item in select key,value from jsonb_each(setting_values->'roles') loop
   if role_name not in ('SUPER_ADMIN','MANAGER','ORDER_MANAGER','INVENTORY_MANAGER','MARKETING_MANAGER','SUPPORT') then raise exception 'Invalid role'; end if;
   for permission_name in select jsonb_array_elements_text(item) loop
    insert into public.staff_permissions(role,permission) values(role_name,permission_name) on conflict do nothing;
   end loop;
  end loop;
  return setting_values;
 end if;
 perform private.require_permission('MANAGE_SETTINGS');
 select * into strict old from public.store_settings where section=setting_section for update;
 if old.version is distinct from expected_version then raise exception 'Settings changed in another session. Reload before saving.'; end if;
 if setting_section='general' then
  if coalesce(setting_values->>'storeName','')='' then raise exception 'Store name is required'; end if;
  if setting_values->>'currency'<>old.values->>'currency' and exists(select 1 from public.orders) then raise exception 'Currency is locked after the first order'; end if;
  if setting_values->>'currency'<>'NGN' then raise exception 'This checkout currently supports NGN only'; end if;
 end if;
 if setting_section='orders' then
  if (setting_values->>'cancellationPeriodMinutes')::integer not between 1 and 10080 or (setting_values->>'returnPeriodDays')::integer not between 0 and 365 then raise exception 'Invalid order periods'; end if;
  -- A single, consistent stock lifecycle: reserve at checkout, deduct after verification.
  if setting_values->>'stockDeduction'<>'PAYMENT' then raise exception 'Inventory deduction is supported after verified payment'; end if;
 end if;
 if setting_section='products' then
  if (setting_values->>'allowOutOfStockPurchases')::boolean then raise exception 'Backorders are not supported; stock is reserved atomically'; end if;
  if jsonb_array_length(setting_values->'sizes')<1 then raise exception 'At least one size is required'; end if;
  delete from public.product_sizes;
  insert into public.product_sizes(name,"sortOrder") select value,ordinality::integer from jsonb_array_elements_text(setting_values->'sizes') with ordinality;
  delete from public.product_colours;
  insert into public.product_colours(name,hex,active) select value->>'name',value->>'hex',(value->>'active')::boolean from jsonb_array_elements(setting_values->'colours');
 end if;
 update public.store_settings set values=setting_values,version=version+1 where section=setting_section returning values into result;
 insert into public.activity_logs("adminId",action,entity,"entityId") values(auth.uid(),'UPDATE','store_settings',setting_section);
 return result;
end; $$;

create function public.published_policy(policy_id text) returns jsonb language sql stable security definer set search_path = '' as $$
 select published from public.policies where id=policy_id and published is not null; $$;
create function public.save_policy(policy_id text, payload jsonb) returns jsonb language plpgsql security definer set search_path = '' as $$
declare result jsonb; old public.policies;
begin
 perform private.require_permission('MANAGE_SETTINGS');
 select * into strict old from public.policies where id=policy_id for update;
 if payload ? 'version' and payload->>'version' is distinct from old."updatedAt"::text and (payload->>'version')::timestamptz is distinct from old."updatedAt" then raise exception 'Policy changed. Reload before saving.'; end if;
 if payload->>'status'='PUBLISHED' and length(trim(regexp_replace(payload->>'content','<[^>]+>','','g')))=0 then raise exception 'Add policy content'; end if;
 update public.policies set title=payload->>'title',content=payload->>'content',status=payload->>'status',
 published=case when payload->>'status'='PUBLISHED' then jsonb_build_object('title',payload->>'title','content',payload->>'content','lastUpdated',now()) else published end
 where id=policy_id returning to_jsonb(policies.*) into result;
 return result;
end; $$;

create function private.notify(event_type text, heading text, detail text, required_permission text, link text default null) returns void language plpgsql security definer set search_path = '' as $$
begin
 if coalesce((select (values->event_type->>'dashboard')::boolean from public.store_settings where section='notifications'),true) then
  insert into public.admin_notifications(type,title,message,permission,"linkUrl") values(event_type,heading,detail,required_permission,link);
 end if;
end; $$;
create function private.stock_alert() returns trigger language plpgsql security definer set search_path = '' as $$
begin
 if coalesce((select (values->>'lowStockNotifications')::boolean from public.store_settings where section='products'),true) and new.quantity-new.reserved<=new."lowStockThreshold" and (tg_op='INSERT' or old.quantity-old.reserved>new.quantity-new.reserved) then
  perform private.notify(case when new.quantity=new.reserved then 'outOfStock' else 'lowStock' end,'Inventory alert',new."variantId"::text||': '||(new.quantity-new.reserved)||' available','MANAGE_INVENTORY','/admin/inventory');
 end if;
 return new;
end; $$;
create trigger stock_alert after insert or update on public.inventory for each row execute function private.stock_alert();

create function public.submit_review(product_id uuid, stars integer, review_text text) returns jsonb language plpgsql security definer set search_path = '' as $$
declare result jsonb;
begin
 if not public.is_customer() or not exists(select 1 from public.orders o join public.order_items i on i."orderId"=o.id where o."customerId"=auth.uid() and o.status='DELIVERED' and i."productId"=product_id) then raise exception 'Only customers with a delivered purchase can review' using errcode='42501'; end if;
 insert into public.product_reviews("productId","customerId",rating,comment) values(product_id,auth.uid(),stars,review_text) returning to_jsonb(product_reviews.*) into result;
 return result;
end; $$;

-- Atomic limits used by the public Edge Function. Keys are HMAC hashes, never raw IPs.
create function public.consume_rate_limit(limit_key text, maximum integer, seconds integer) returns boolean language plpgsql security definer set search_path = '' as $$
declare n integer;
begin
 insert into private.rate_limits(key,hits) values(limit_key,1) on conflict(key) do update set
 hits=case when private.rate_limits.start_at<now()-make_interval(secs=>seconds) then 1 else private.rate_limits.hits+1 end,
 start_at=case when private.rate_limits.start_at<now()-make_interval(secs=>seconds) then now() else private.rate_limits.start_at end returning hits into n;
 return n<=maximum;
end; $$;
revoke execute on function public.consume_rate_limit(text,integer,integer) from public,anon,authenticated;
grant execute on function public.consume_rate_limit(text,integer,integer) to service_role;

-- END 202610310004_operations.sql


-- BEGIN 202610310005_checkout.sql
create function private.release_order(target uuid, explanation text) returns void language plpgsql security definer set search_path = '' as $$
declare o public.orders; i record;
begin
 select * into strict o from public.orders where id=target for update;
 if o.status<>'PENDING' or o."stockCommitted" then return; end if;
 for i in select * from public.order_items where "orderId"=o.id order by "variantId" loop
  update public.inventory set reserved=reserved-i.quantity where "variantId"=i."variantId";
  insert into public.inventory_movements("variantId",delta,"reservedDelta",type,reason,"orderId","actorId") values(i."variantId",0,-i.quantity,'CANCELLATION',explanation,o.id,auth.uid());
 end loop;
 update public.orders set status='CANCELLED' where id=o.id;
 delete from public.coupon_usage where "orderId"=o.id;
 insert into public.order_status_history("orderId",status,note,"actorId") values(o.id,'CANCELLED',explanation,auth.uid());
 insert into public.notifications("customerId",title,message,"linkUrl") values(o."customerId",'Order cancelled',explanation,'/account/orders/'||o.id);
 perform private.notify('cancelledOrder','Order cancelled',o."orderNumber"||': '||explanation,'VIEW_ORDERS','/admin/orders?view='||o.id);
end; $$;
create function public.expire_orders() returns integer language plpgsql security definer set search_path = '' as $$
declare o record; n integer=0;
begin
 for o in select id from public.orders where status='PENDING' and "expiresAt"<now() order by id for update skip locked loop
  perform private.release_order(o.id,'Payment reservation expired'); n=n+1;
 end loop;
 return n;
end; $$;
revoke execute on function public.expire_orders() from public,anon,authenticated;
grant execute on function public.expire_orders() to service_role;

create function public.create_checkout(payload jsonb) returns jsonb language plpgsql security definer set search_path = '' as $$
declare uid uuid=auth.uid(); cart_id uuid; o public.orders; z public.shipping_zones; c public.coupons;
 cfg jsonb; general jsonb; ship jsonb; addr jsonb=payload->'shippingAddress'; it record; sub numeric=0; discount numeric=0; fee numeric;
 oid uuid=gen_random_uuid(); item_price numeric; n integer=0; line jsonb; lines jsonb='[]'; existing uuid; v integer; threshold numeric;
begin
 if uid is null or not public.is_customer() then raise exception 'Please sign in to checkout' using errcode='42501'; end if;
 -- Per-customer serialization ensures retry and cart mutation cannot create duplicate orders.
 perform pg_advisory_xact_lock(hashtextextended(uid::text,0));
 select id into existing from public.orders where "customerId"=uid and "idempotencyKey"=(payload->>'idempotencyKey')::uuid;
 if existing is not null then return (select to_jsonb(x.*) from public.orders x where id=existing); end if;
 select values into cfg from public.store_settings where section='orders';
 select values into general from public.store_settings where section='general';
 select values into ship from public.store_settings where section='shipping';
 if general->>'status'<>'ACTIVE' then raise exception 'Store checkout is paused'; end if;
 if general->>'currency'<>'NGN' then raise exception 'Checkout supports NGN only'; end if;
 foreach line in array array[addr] loop
  if jsonb_typeof(line)<>'object' then raise exception 'Delivery address required'; end if;
 end loop;
 if exists(select 1 from unnest(array['recipient','phoneNumber','street','city','state','country']) k where length(trim(coalesce(addr->>k,''))) not between 1 and 500) then raise exception 'Complete your delivery address'; end if;
 select * into strict z from public.shipping_zones where id=(payload->>'deliveryZoneId')::uuid and "isActive";
 if lower(z.country)<>lower(addr->>'country') or not exists(select 1 from unnest(z.states) s where lower(s)=lower(addr->>'state')) then raise exception 'Delivery zone does not match address'; end if;
 insert into public.carts("customerId") values(uid) on conflict("customerId") do nothing;
 select id into cart_id from public.carts where "customerId"=uid for update;
 -- Lock variants/products against price changes, then inventory in deterministic order.
 for it in select ci.quantity,ci."variantId",p.id as product_id,p.name,p.price,v.sku,v.size,v.color,v."priceDiff",p."isActive" as published,p."archivedAt",v."isActive" as enabled
  from public.cart_items ci join public.product_variants v on v.id=ci."variantId" join public.products p on p.id=v."productId"
  where ci."cartId"=cart_id order by ci."variantId" for share of ci,v,p loop
  n=n+1;
  if not it.published or not it.enabled or it."archivedAt" is not null then raise exception 'An item is no longer available'; end if;
  select quantity-reserved into v from public.inventory where "variantId"=it."variantId" for update;
  if v is null or v<it.quantity then raise exception 'Insufficient stock for % / % / %',it.name,it.size,it.color; end if;
  item_price=it.price+it."priceDiff";
  if item_price<0 then raise exception 'Invalid variant price'; end if;
  select greatest(0,item_price-coalesce(max(case when d."discountType"='PERCENTAGE' then round(item_price*d.value/100,2) else d.value end),0)) into item_price
   from public.discounts d where d."productId"=it.product_id and d."isActive" and (d."startsAt" is null or d."startsAt"<=now()) and (d."expiresAt" is null or d."expiresAt">now());
  if item_price<0 then raise exception 'Invalid variant price'; end if;
  sub=sub+item_price*it.quantity;
  lines=lines||jsonb_build_array(jsonb_build_object('variantId',it."variantId",'productId',it.product_id,'productName',it.name,'sku',it.sku,'size',it.size,'color',it.color,'quantity',it.quantity,'unitPrice',item_price));
 end loop;
 if n=0 then raise exception 'Your cart is empty'; end if;
 if coalesce(payload->>'couponCode','')<>'' then
  select * into c from public.coupons where code=upper(trim(payload->>'couponCode')) for update;
  if c.id is null or not c."isActive" or c."startsAt">now() or c."expiresAt"<=now() or sub<c."minSpend" then raise exception 'Coupon is not valid for this order'; end if;
  if c."usageLimit" is not null and (select count(*) from public.coupon_usage where "couponId"=c.id)>=c."usageLimit" then raise exception 'Coupon usage limit reached'; end if;
  if (select count(*) from public.coupon_usage where "couponId"=c.id and "customerId"=uid)>=c."perCustomerLimit" then raise exception 'You have already used this coupon'; end if;
  discount=case when c."discountType"='PERCENTAGE' then round(sub*c.value/100,2) else c.value end;
  discount=least(sub,discount,coalesce(c."maxDiscount",sub));
 end if;
 threshold=coalesce(z."freeDeliveryThreshold",(ship->>'freeDeliveryThreshold')::numeric);
 fee=case when threshold is not null and sub-discount>=threshold then 0 else z.fee end;
 if sub-discount+fee<=0 then raise exception 'This checkout requires a positive total. Contact NOBELLE for fully discounted orders.'; end if;
 insert into public.orders(id,"customerId","orderNumber","idempotencyKey",subtotal,"discountTotal","deliveryFee","totalAmount",currency,"deliveryZoneId","expiresAt","settingsSnapshot")
 values(oid,uid,coalesce(cfg->>'prefix','NBL-')||upper(replace(oid::text,'-','')),(payload->>'idempotencyKey')::uuid,sub,discount,fee,sub-discount+fee,'NGN',z.id,now()+make_interval(mins=>(cfg->>'cancellationPeriodMinutes')::integer),cfg) returning * into o;
 insert into public.shipping_addresses("orderId",recipient,"phoneNumber",street,city,state,country,"postalCode") values(oid,addr->>'recipient',addr->>'phoneNumber',addr->>'street',addr->>'city',addr->>'state',addr->>'country',addr->>'postalCode');
 for line in select value from jsonb_array_elements(lines) loop
  insert into public.order_items("orderId","productId","variantId","productName",sku,size,color,quantity,"unitPrice","totalPrice") values(oid,(line->>'productId')::uuid,(line->>'variantId')::uuid,line->>'productName',line->>'sku',line->>'size',line->>'color',(line->>'quantity')::integer,(line->>'unitPrice')::numeric,(line->>'unitPrice')::numeric*(line->>'quantity')::integer);
  update public.inventory set reserved=reserved+(line->>'quantity')::integer where "variantId"=(line->>'variantId')::uuid;
  insert into public.inventory_movements("variantId",delta,"reservedDelta",type,reason,"orderId","actorId") values((line->>'variantId')::uuid,0,(line->>'quantity')::integer,'RESERVATION','Checkout reservation',oid,uid);
 end loop;
 if c.id is not null then insert into public.coupon_usage("couponId","customerId","orderId") values(c.id,uid,oid); end if;
 delete from public.cart_items where "cartId"=cart_id;
 insert into public.order_status_history("orderId",status,"actorId") values(oid,'PENDING',uid);
 perform private.notify('newOrder','New order',o."orderNumber",'VIEW_ORDERS','/admin/orders?view='||oid);
 return to_jsonb(o);
end; $$;

create function public.cancel_order(order_id uuid) returns void language plpgsql security definer set search_path = '' as $$
declare o public.orders;
begin
 select * into strict o from public.orders where id=order_id for update;
 if not public.has_permission('CANCEL_ORDERS') and not (o."customerId"=auth.uid() and public.is_customer() and (o."settingsSnapshot"->>'allowCancellation')::boolean and o."expiresAt">now()) then raise exception 'Cancellation not permitted' using errcode='42501'; end if;
 if o.status<>'PENDING' or o."stockCommitted" then raise exception 'Only unpaid pending orders can be cancelled'; end if;
 perform private.release_order(order_id,'Cancelled by customer or staff');
end; $$;

create function public.transition_order(order_id uuid, next_status text) returns jsonb language plpgsql security definer set search_path = '' as $$
declare o public.orders;
begin
 if next_status='CANCELLED' then perform public.cancel_order(order_id); return (select to_jsonb(x.*) from public.orders x where id=order_id); end if;
 perform private.require_permission('UPDATE_ORDERS');
 select * into strict o from public.orders where id=order_id for update;
 if o."paymentStatus"<>'SUCCESS' then raise exception 'Payment must be verified before fulfilment'; end if;
 if not ((o.status='PENDING' and next_status='CONFIRMED') or (o.status='CONFIRMED' and next_status='PROCESSING') or (o.status='PROCESSING' and next_status='SHIPPED') or (o.status='SHIPPED' and next_status='DELIVERED')) then raise exception 'Invalid order status transition'; end if;
 update public.orders set status=next_status,"deliveredAt"=case when next_status='DELIVERED' then now() else "deliveredAt" end where id=order_id returning * into o;
 insert into public.order_status_history("orderId",status,"actorId") values(order_id,next_status,auth.uid());
 insert into public.notifications("customerId",title,message,"linkUrl") values(o."customerId",'Order update',o."orderNumber"||': '||next_status,'/account/orders/'||o.id);
 return to_jsonb(o);
end; $$;

create function public.save_shipment(order_id uuid, carrier_name text, tracking_number text) returns void language plpgsql security definer set search_path = '' as $$
begin
 perform private.require_permission('UPDATE_ORDERS');
 if length(trim(carrier_name))=0 or length(trim(tracking_number))=0 then raise exception 'Carrier and tracking number required'; end if;
 if not exists(select 1 from public.orders where id=order_id and status in ('PROCESSING','SHIPPED')) then raise exception 'Order is not ready for shipping'; end if;
 insert into public.shipments("orderId",carrier,"trackingNumber") values(order_id,carrier_name,tracking_number) on conflict("orderId") do update set carrier=excluded.carrier,"trackingNumber"=excluded."trackingNumber";
end; $$;

-- Service-role only: the Edge Function verifies Paystack, including exact amount,
-- currency, reference, gateway ID and test/live domain before invoking this.
create function public.settle_payment(payment_reference text, gateway_id text, amount_minor bigint, payment_currency text, gateway_mode text, successful boolean) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare p public.payments; o public.orders; i record;
begin
 -- Lock order first everywhere to avoid cancellation/webhook lock inversion.
 select o1.* into strict o from public.orders o1 join public.payments p1 on p1."orderId"=o1.id where p1.reference=payment_reference for update of o1;
 select * into strict p from public.payments where reference=payment_reference for update;
 if round(p.amount*100)::bigint<>amount_minor or p.currency<>payment_currency or p.mode<>gateway_mode then raise exception 'Payment amount, currency or mode mismatch'; end if;
 if p.status in ('SUCCESS','REFUNDED') then return to_jsonb(p); end if;
 if successful and (o.status='CANCELLED' or o."expiresAt"<now()) then
  -- Preserve funds received after expiry as a verified payment requiring staff refund.
  update public.payments set status='SUCCESS',"gatewayId"=gateway_id where id=p.id returning * into p;
  insert into public.payment_transactions("paymentId","eventId",status,amount) values(p.id,'charge:'||gateway_id,'SUCCESS',p.amount) on conflict("eventId") do nothing;
  perform private.release_order(o.id,'Late payment received; staff refund required');
  perform private.notify('successfulPayment','Late payment requires refund',o."orderNumber",'PROCESS_REFUNDS','/admin/payments');
  return to_jsonb(p);
 end if;
 if successful then
  for i in select * from public.order_items where "orderId"=o.id order by "variantId" loop
   update public.inventory set quantity=quantity-i.quantity,reserved=reserved-i.quantity where "variantId"=i."variantId";
   update public.products set "soldCount"="soldCount"+i.quantity where id=i."productId";
   insert into public.inventory_movements("variantId",delta,"reservedDelta",type,reason,"orderId") values(i."variantId",-i.quantity,-i.quantity,'SALE','Verified Paystack payment',o.id);
  end loop;
  update public.orders set "paymentStatus"='SUCCESS',"stockCommitted"=true,"paidAt"=now(),status=case when "settingsSnapshot"->>'confirmation'='AUTOMATIC' then 'CONFIRMED' else 'PENDING' end where id=o.id returning * into o;
  insert into public.order_status_history("orderId",status,note) values(o.id,o.status,'Payment verified');
  update public.payments set status='SUCCESS',"gatewayId"=gateway_id where id=p.id returning * into p;
  perform private.notify('successfulPayment','Payment received',o."orderNumber",'VIEW_PAYMENTS','/admin/payments');
 else
  update public.payments set status='FAILED',"gatewayId"=gateway_id where id=p.id returning * into p;
  update public.orders set "paymentStatus"='FAILED' where id=o.id;
  perform private.release_order(o.id,'Payment failed');
  perform private.notify('failedPayment','Payment failed',o."orderNumber",'VIEW_PAYMENTS','/admin/payments');
 end if;
 insert into public.payment_transactions("paymentId","eventId",status,amount) values(p.id,'charge:'||gateway_id||':'||p.status,p.status,p.amount) on conflict("eventId") do nothing;
 insert into public.notifications("customerId",title,message,"linkUrl") values(o."customerId",'Payment update',o."orderNumber"||': '||p.status,'/account/orders/'||o.id);
 return to_jsonb(p);
end; $$;
revoke execute on function public.settle_payment(text,text,bigint,text,text,boolean) from public,anon,authenticated;
grant execute on function public.settle_payment(text,text,bigint,text,text,boolean) to service_role;

create function public.request_return(payload jsonb) returns jsonb language plpgsql security definer set search_path = '' as $$
declare o public.orders; ri jsonb; oi public.order_items; rid uuid; prior integer; result jsonb;
begin
 select * into strict o from public.orders where id=(payload->>'orderId')::uuid for update;
 if o."customerId"<>auth.uid() or not public.is_customer() or o.status<>'DELIVERED' then raise exception 'Return not permitted' using errcode='42501'; end if;
 if (o."settingsSnapshot"->>'returnPeriodDays')::integer=0 or o."deliveredAt"+make_interval(days=>(o."settingsSnapshot"->>'returnPeriodDays')::integer)<now() then raise exception 'Return period has ended'; end if;
 if jsonb_array_length(payload->'items')<1 then raise exception 'Select return items'; end if;
 insert into public.returns("orderId","customerId",reason) values(o.id,auth.uid(),payload->>'reason') returning id into rid;
 for ri in select value from jsonb_array_elements(payload->'items') loop
  select * into strict oi from public.order_items where id=(ri->>'orderItemId')::uuid and "orderId"=o.id;
  select coalesce(sum(i.quantity),0) into prior from public.return_items i join public.returns r on r.id=i."returnId" where i."orderItemId"=oi.id and r.status<>'REJECTED';
  if (ri->>'quantity')::integer+prior>oi.quantity then raise exception 'Return exceeds purchased quantity'; end if;
  insert into public.return_items("returnId","orderItemId",quantity) values(rid,oi.id,(ri->>'quantity')::integer);
 end loop;
 perform private.notify('returnRequest','Return requested',o."orderNumber",'VIEW_ORDERS','/admin/returns');
 return (select to_jsonb(r.*) from public.returns r where id=rid);
end; $$;
create function public.transition_return(return_id uuid, next_status text) returns jsonb language plpgsql security definer set search_path = '' as $$
declare r public.returns;
begin
 perform private.require_permission('UPDATE_ORDERS'); select * into strict r from public.returns where id=return_id for update;
 if not ((r.status='REQUESTED' and next_status in ('UNDER_REVIEW','APPROVED','REJECTED')) or (r.status='UNDER_REVIEW' and next_status in ('APPROVED','REJECTED')) or (r.status='APPROVED' and next_status='RECEIVED') or (r.status='REFUNDED' and next_status='COMPLETED')) then raise exception 'Invalid return transition'; end if;
 update public.returns set status=next_status where id=return_id returning * into r; return to_jsonb(r);
end; $$;

create function public.prepare_refund(return_id uuid) returns jsonb language plpgsql security definer set search_path = '' as $$
declare r public.returns; o public.orders; p public.payments; amount numeric; ref public.refunds;
begin
 perform private.require_permission('PROCESS_REFUNDS');
 select * into strict r from public.returns where id=return_id for update;
 select * into strict o from public.orders where id=r."orderId" for update;
 if r.status not in ('RECEIVED','REFUNDED') or o."settingsSnapshot"->>'refundRule'='DISABLED' then raise exception 'Return must be received and refunds enabled'; end if;
 select * into strict p from public.payments where "orderId"=o.id and status='SUCCESS' for update;
 select round(sum(i.quantity*oi."unitPrice")*(o.subtotal-o."discountTotal")/nullif(o.subtotal,0),2) into amount from public.return_items i join public.order_items oi on oi.id=i."orderItemId" where i."returnId"=r.id;
 amount=least(amount,o.subtotal-o."discountTotal"-coalesce((select sum(f.amount) from public.refunds f where f."paymentId"=p.id and f."returnId"<>r.id),0));
 if amount is null or amount<=0 then raise exception 'Invalid refund total'; end if;
 insert into public.refunds("returnId","paymentId",amount) values(r.id,p.id,amount) on conflict("returnId") do nothing;
 select * into strict ref from public.refunds where "returnId"=r.id;
 return to_jsonb(ref)||jsonb_build_object('reference',p.reference);
end; $$;
create function public.settle_refund(refund_id uuid, gateway_id text, refund_status text) returns void language plpgsql security definer set search_path = '' as $$
declare ref public.refunds; r public.returns; p public.payments; item record;
begin
 select * into strict ref from public.refunds where id=refund_id for update;
 if ref.status='SUCCESS' then return; end if;
 if refund_status not in ('PENDING','FAILED','SUCCESS') then raise exception 'Invalid refund status'; end if;
 update public.refunds set status=refund_status,"gatewayId"=gateway_id where id=ref.id;
 if refund_status<>'SUCCESS' then return; end if;
 select * into strict r from public.returns where id=ref."returnId" for update;
 select * into strict p from public.payments where id=ref."paymentId" for update;
 for item in select i.quantity,oi."variantId" from public.return_items i join public.order_items oi on oi.id=i."orderItemId" where i."returnId"=r.id order by oi."variantId" loop
  update public.inventory set quantity=quantity+item.quantity where "variantId"=item."variantId";
  update public.products set "soldCount"=greatest(0,"soldCount"-item.quantity) where id=(select "productId" from public.product_variants where id=item."variantId");
  insert into public.inventory_movements("variantId",delta,type,reason,"orderId") values(item."variantId",item.quantity,'RETURN','Verified refund for received goods',r."orderId");
 end loop;
 update public.refunds set "restockedAt"=now() where id=ref.id;
 update public.returns set status='REFUNDED' where id=r.id;
 if not exists(select 1 from public.order_items oi where oi."orderId"=r."orderId" and oi.quantity>(select coalesce(sum(ri.quantity),0) from public.return_items ri join public.returns rr on rr.id=ri."returnId" where ri."orderItemId"=oi.id and rr.status in ('REFUNDED','COMPLETED'))) then
  update public.orders set status='REFUNDED',"paymentStatus"='REFUNDED' where id=r."orderId";
  update public.payments set status='REFUNDED' where id=p.id;
  insert into public.order_status_history("orderId",status,note) values(r."orderId",'REFUNDED','All purchased items refunded');
 end if;
 insert into public.notifications("customerId",title,message,"linkUrl") values(r."customerId",'Refund completed','Your returned items have been refunded.','/account/orders/'||r."orderId");
end; $$;
revoke execute on function public.settle_refund(uuid,text,text) from public,anon,authenticated;
grant execute on function public.settle_refund(uuid,text,text) to service_role;

-- Optional managed cron is installed separately (see SETUP.md); checkout also expires
-- old reservations via the service Edge Function before creating a new order.

-- END 202610310005_checkout.sql


-- BEGIN 202610310006_reporting.sql
create function public.admin_report(date_from timestamptz default '-infinity', date_to timestamptz default 'infinity') returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare result jsonb;
begin
 perform private.require_permission('VIEW_ANALYTICS');
 with paid as (select o.*,greatest(0,o."totalAmount"-coalesce((select sum(r.amount) from public.refunds r join public.payments p on p.id=r."paymentId" where p."orderId"=o.id and r.status='SUCCESS'),0)) net
 from public.orders o where o."paidAt" between date_from and date_to and o."stockCommitted"),
 daily as (select ("paidAt" at time zone 'Africa/Lagos')::date as date,sum(net) revenue,count(*) orders from paid group by 1 order by 1),
 net_items as (select i.*,i.quantity-coalesce((select sum(ri.quantity) from public.return_items ri join public.returns r on r.id=ri."returnId" where ri."orderItemId"=i.id and r.status in ('REFUNDED','COMPLETED')),0) net_quantity,p.subtotal,p."discountTotal" from public.order_items i join paid p on p.id=i."orderId"),
 best as (select i."productId",i."productName",sum(i.net_quantity) quantity,sum(i."unitPrice"*i.net_quantity*(i.subtotal-i."discountTotal")/nullif(i.subtotal,0)) revenue from net_items i group by 1,2 order by sum(i.net_quantity) desc),
 cats as (select coalesce(c.name,'Uncategorised') name,sum(i.net_quantity) quantity,sum(i."unitPrice"*i.net_quantity*(i.subtotal-i."discountTotal")/nullif(i.subtotal,0)) revenue from net_items i join public.products pr on pr.id=i."productId" left join public.product_categories c on c.id=pr."categoryId" group by 1),
 growth as (select ("createdAt" at time zone 'Africa/Lagos')::date date,count(*) customers from public.profiles where "createdAt" between date_from and date_to group by 1 order by 1),
 movements as (select type,jsonb_build_object('delta',sum(delta)) "_sum",count(*) "_count" from public.inventory_movements where "createdAt" between date_from and date_to group by type)
 select jsonb_build_object('revenue',coalesce((select sum(net) from paid),0),'orders',(select count(*) from paid),
 'averageOrderValue',coalesce((select avg(net) from paid),0),'productsSold',coalesce((select sum(net_quantity) from net_items),0),
 'daily',coalesce((select jsonb_agg(daily) from daily),'[]'),'bestSellers',coalesce((select jsonb_agg(best) from best),'[]'),
 'categories',coalesce((select jsonb_agg(cats) from cats),'[]'),'customerGrowth',coalesce((select jsonb_agg(growth) from growth),'[]'),
 'inventoryMovement',coalesce((select jsonb_agg(movements) from movements),'[]')) into result;
 return result;
end; $$;
create function public.admin_dashboard() returns jsonb language plpgsql stable security definer set search_path = '' as $$
begin
 perform private.require_permission('VIEW_ANALYTICS');
 return jsonb_build_object('totalOrders',(select count(*) from public.orders),'totalCustomers',(select count(*) from public.profiles p where not exists(select 1 from public.admin_roles a where a."userId"=p.id)),
 'totalProducts',(select count(*) from public.products where "archivedAt" is null),'totalStock',(select coalesce(sum(quantity-reserved),0) from public.inventory),
 'lowStockCount',(select count(*) from public.inventory where quantity-reserved between 1 and "lowStockThreshold"),
 'outOfStockCount',(select count(*) from public.inventory where quantity=reserved),
 'statusCounts',(select coalesce(jsonb_agg(s),'[]') from (select status,count(*) "_count" from public.orders group by status) s),
 'recentOrders',(select coalesce(jsonb_agg(r),'[]') from (select o.*,jsonb_build_object('firstName',p."firstName",'lastName',p."lastName",'email',p.email) customer,
 coalesce((select jsonb_agg(jsonb_build_object('status',pay.status)) from public.payments pay where pay."orderId"=o.id),'[]') payments
 from public.orders o join public.profiles p on p.id=o."customerId" order by o."createdAt" desc limit 10) r));
end; $$;

create function public.admin_customer(customer_id uuid) returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare p public.profiles;
begin
 perform private.require_permission('VIEW_CUSTOMERS'); select * into strict p from public.profiles where id=customer_id;
 return to_jsonb(p)||jsonb_build_object('orders',(select coalesce(jsonb_agg(o),'[]') from (select * from public.orders where "customerId"=customer_id order by "createdAt" desc limit 50) o),
 '_count',jsonb_build_object('orders',(select count(*) from public.orders where "customerId"=customer_id)),
 'totalSpent',(select coalesce(sum(o."totalAmount"-coalesce((select sum(f.amount) from public.refunds f join public.payments p1 on p1.id=f."paymentId" where p1."orderId"=o.id and f.status='SUCCESS'),0)),0) from public.orders o where o."customerId"=customer_id and o."stockCommitted"),
 'addresses',(select coalesce(jsonb_agg(a),'[]') from (select * from public.customer_addresses where "customerId"=customer_id limit 20) a),
 'returns',(select coalesce(jsonb_agg(r),'[]') from (select * from public.returns where "customerId"=customer_id limit 20) r),
 'wishlist',jsonb_build_object('items',(select coalesce(jsonb_agg(x),'[]') from (select wi.id,jsonb_build_object('id',pr.id,'name',pr.name) product from public.wishlist_items wi join public.wishlists w on w.id=wi."wishlistId" join public.products pr on pr.id=wi."productId" where w."customerId"=customer_id limit 50) x)));
end; $$;

-- Guard against a staff member removing the last administrator, including via the
-- service-only staff management Edge Function.
create function private.protect_super_admin() returns trigger language plpgsql security definer set search_path = '' as $$
begin
 perform pg_advisory_xact_lock(731934);
 if old.role='SUPER_ADMIN' and old."isActive" and (tg_op='DELETE' or new.role<>'SUPER_ADMIN' or not new."isActive")
 and not exists(select 1 from public.admin_roles where id<>old.id and role='SUPER_ADMIN' and "isActive") then raise exception 'Keep at least one active Super Admin'; end if;
 if tg_op='DELETE' then return old; end if; return new;
end; $$;
create trigger protect_super_admin before update or delete on public.admin_roles for each row execute function private.protect_super_admin();

-- Functions default to EXECUTE for PUBLIC in PostgreSQL. Restrict application
-- operations explicitly; only the published policy reader is available anonymously.
do $$ declare routine record; begin
 for routine in select p.oid::regprocedure identity from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=any(array['has_permission','is_customer','admin_write','adjust_inventory','save_content','save_settings','published_policy','save_policy','submit_review','consume_rate_limit','expire_orders','create_checkout','cancel_order','transition_order','save_shipment','settle_payment','request_return','transition_return','prepare_refund','settle_refund','admin_report','admin_dashboard','admin_customer']) loop
  execute format('revoke execute on function %s from public,anon',routine.identity);
 end loop;
end $$;
grant execute on function public.has_permission(text),public.is_customer(),public.published_policy(text) to anon,authenticated;
grant execute on function public.admin_write(text,uuid,jsonb,text),public.adjust_inventory(uuid,integer,text),public.save_content(text,jsonb),public.save_settings(text,jsonb,integer),public.save_policy(text,jsonb),public.submit_review(uuid,integer,text),public.create_checkout(jsonb),public.cancel_order(uuid),public.transition_order(uuid,text),public.save_shipment(uuid,text,text),public.request_return(jsonb),public.transition_return(uuid,text),public.prepare_refund(uuid),public.admin_report(timestamptz,timestamptz),public.admin_dashboard(),public.admin_customer(uuid) to authenticated;
-- Repeat service-only grants after revoking default PUBLIC grants.
grant execute on function public.consume_rate_limit(text,integer,integer),public.expire_orders(),public.settle_payment(text,text,bigint,text,text,boolean),public.settle_refund(uuid,text,text) to service_role;

-- END 202610310006_reporting.sql


-- BEGIN 202610310007_addresses.sql
create function public.save_address(address_id uuid,payload jsonb) returns jsonb language plpgsql security definer set search_path = '' as $$
declare uid uuid=auth.uid(); result jsonb; old public.customer_addresses;
begin
 if not public.is_customer() then raise exception 'Sign in to save addresses' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended(uid::text,0));
 if address_id is not null then select * into strict old from public.customer_addresses where id=address_id and "customerId"=uid for update; end if;
 if coalesce((payload->>'isDefault')::boolean,false) then update public.customer_addresses set "isDefault"=false where "customerId"=uid; end if;
 if address_id is null then
  insert into public.customer_addresses("customerId",recipient,"phoneNumber",street,city,state,country,"postalCode","isDefault") values(uid,payload->>'recipient',payload->>'phoneNumber',payload->>'street',payload->>'city',payload->>'state',coalesce(payload->>'country','Nigeria'),payload->>'postalCode',coalesce((payload->>'isDefault')::boolean,false)) returning to_jsonb(customer_addresses.*) into result;
 else
  update public.customer_addresses set recipient=coalesce(payload->>'recipient',old.recipient),"phoneNumber"=coalesce(payload->>'phoneNumber',old."phoneNumber"),street=coalesce(payload->>'street',old.street),city=coalesce(payload->>'city',old.city),state=coalesce(payload->>'state',old.state),country=coalesce(payload->>'country',old.country),"postalCode"=coalesce(payload->>'postalCode',old."postalCode"),"isDefault"=coalesce((payload->>'isDefault')::boolean,old."isDefault") where id=address_id and "customerId"=uid returning to_jsonb(customer_addresses.*) into result;
 end if;
 return result;
end; $$;
revoke execute on function public.save_address(uuid,jsonb) from public,anon;
grant execute on function public.save_address(uuid,jsonb) to authenticated;
drop policy own_addresses on public.customer_addresses;
create policy own_addresses on public.customer_addresses for select to authenticated using(("customerId"=auth.uid() and public.is_customer()) or public.has_permission('VIEW_CUSTOMERS'));
create policy delete_own_address on public.customer_addresses for delete to authenticated using("customerId"=auth.uid() and public.is_customer());
revoke insert,update on public.customer_addresses from authenticated;

-- END 202610310007_addresses.sql


