 select coalesce(jsonb_object_agg(id,"soldCount"),'{}') from public.products where "isActive" and "archivedAt" is null;
$$;
revoke execute on function public.product_popularity() from public;
grant execute on function public.product_popularity() to anon,authenticated;

-- END 202610310009_hardening.sql


-- BEGIN 202610310010_sessions.sql
-- A revoked Supabase session loses private data access immediately, even while
-- an already-issued access JWT has time remaining before expiry.
create function private.session_valid() returns boolean language sql stable security definer set search_path = '' as $$
 select case when auth.jwt()->>'session_id' is null then false else
 exists(select 1 from auth.sessions where id=(auth.jwt()->>'session_id')::uuid and user_id=auth.uid()) end;
$$;
create or replace function public.has_permission(required text) returns boolean language sql stable security definer set search_path = '' as $$
 select private.session_valid() and exists(select 1 from public.admin_roles a join public.profiles p on p.id=a."userId"
 where a."userId"=auth.uid() and a."isActive" and p."isActive" and
 (a.role='SUPER_ADMIN' or exists(select 1 from public.staff_permissions s where s.role=a.role and s.permission=required)));
$$;
create or replace function public.is_customer() returns boolean language sql stable security definer set search_path = '' as $$
 select private.session_valid() and exists(select 1 from public.profiles where id=auth.uid() and "isActive");
$$;
create function public.admin_security_data() returns jsonb language plpgsql stable security definer set search_path = '' as $$
begin
 if not public.is_customer() or not exists(select 1 from public.admin_roles where "userId"=auth.uid() and "isActive") then raise exception 'Access denied' using errcode='42501'; end if;
 return jsonb_build_object('sessions',(select coalesce(jsonb_agg(s),'[]') from (
  select id,created_at "loginAt",updated_at "lastActiveAt",id::text=auth.jwt()->>'session_id' as current,
  case when user_agent ilike '%Windows%' then 'Windows' when user_agent ilike '%Android%' then 'Android' when user_agent ilike '%iPhone%' then 'iPhone' when user_agent ilike '%Mac%' then 'Mac' else 'Browser' end device,
  case when user_agent ilike '%Firefox%' then 'Firefox' when user_agent ilike '%Edg/%' then 'Edge' when user_agent ilike '%Chrome%' then 'Chrome' when user_agent ilike '%Safari%' then 'Safari' else '' end browser
  from auth.sessions where user_id=auth.uid() order by created_at desc) s),
 'history',(select coalesce(jsonb_agg(h),'[]') from (select id,"createdAt" date,'Supabase Auth' device,'' browser,'SUCCESS' status from public.activity_logs where "adminId"=auth.uid() and action='LOGIN' order by "createdAt" desc limit 30) h));
end; $$;
create function public.revoke_admin_session(session_id uuid) returns void language plpgsql security definer set search_path = '' as $$
begin
 if not public.is_customer() or not exists(select 1 from public.admin_roles where "userId"=auth.uid() and "isActive") then raise exception 'Access denied' using errcode='42501'; end if;
 if session_id::text=auth.jwt()->>'session_id' then raise exception 'Use Sign out for your current session'; end if;
 delete from auth.sessions where id=session_id and user_id=auth.uid();
end; $$;
revoke execute on function public.admin_security_data(),public.revoke_admin_session(uuid) from public,anon;
grant execute on function public.admin_security_data(),public.revoke_admin_session(uuid) to authenticated;
drop policy own_profile on public.profiles;
create policy own_profile on public.profiles for select to authenticated using((id=auth.uid() and public.is_customer()) or public.has_permission('VIEW_CUSTOMERS') or public.has_permission('MANAGE_STAFF'));
drop policy own_role on public.admin_roles;
create policy own_role on public.admin_roles for select to authenticated using(("userId"=auth.uid() and public.is_customer()) or public.has_permission('MANAGE_STAFF'));

-- END 202610310010_sessions.sql


-- BEGIN 202610310011_email_notifications.sql
-- Optional business-event email delivery. Auth emails remain with Supabase Auth.
create table public.email_outbox (
 id uuid primary key default gen_random_uuid(), recipient text not null, subject text not null, body text not null,
 "linkUrl" text, status text not null default 'PENDING' check(status in ('PENDING','PROCESSING','SENT','FAILED')),
 attempts integer not null default 0, "firstAttemptAt" timestamptz, "lockedUntil" timestamptz,
 "notBefore" timestamptz not null default now(), "providerId" text, "lastError" text,
 "createdAt" timestamptz not null default now(), "updatedAt" timestamptz not null default now()
);
alter table public.email_outbox enable row level security;
revoke all on public.email_outbox from anon,authenticated;
grant select on public.email_outbox to authenticated;
grant all on public.email_outbox to service_role;
create policy email_settings_staff on public.email_outbox for select to authenticated using(public.has_permission('MANAGE_SETTINGS'));
create index email_outbox_pending on public.email_outbox("notBefore") where status in ('PENDING','PROCESSING');
create trigger email_touch before update on public.email_outbox for each row execute function private.touch_updated_at();

create or replace function private.notify(event_type text, heading text, detail text, required_permission text, link text default null) returns void language plpgsql security definer set search_path = '' as $$
declare preferences jsonb; business_email text;
begin
 if event_type='newOrder' and not coalesce((select (values->>'orderNotifications')::boolean from public.store_settings where section='orders'),true) then return; end if;
 select values->event_type into preferences from public.store_settings where section='notifications';
 if coalesce((preferences->>'dashboard')::boolean,true) then
  insert into public.admin_notifications(type,title,message,permission,"linkUrl") values(event_type,heading,detail,required_permission,link);
 end if;
 if coalesce((preferences->>'email')::boolean,false) then
  select nullif(trim(values->>'businessEmail'),'') into business_email from public.store_settings where section='store';
  if business_email is not null then
   insert into public.email_outbox(recipient,subject,body,"linkUrl") values(business_email,heading,detail,link);
  else
   insert into public.email_outbox(recipient,subject,body,"linkUrl") select distinct p.email,heading,detail,link from public.profiles p join public.admin_roles a on a."userId"=p.id where a.role='SUPER_ADMIN' and a."isActive" and p."isActive";
  end if;
 end if;
end; $$;

create function public.claim_email_batch() returns setof public.email_outbox language plpgsql security definer set search_path = '' as $$
begin
 -- Provider idempotency has a 24h lifetime. Never resend an uncertain old request.
 update public.email_outbox set status='FAILED',"lastError"='Delivery outcome uncertain; reconcile with the email provider' where status in ('PENDING','PROCESSING') and "firstAttemptAt"<now()-interval '23 hours';
 return query with picked as (
  select id from public.email_outbox where attempts<5 and "notBefore"<=now() and (status='PENDING' or status='PROCESSING' and "lockedUntil"<now()) order by "createdAt" for update skip locked limit 5
 ) update public.email_outbox e set status='PROCESSING',attempts=attempts+1,"firstAttemptAt"=coalesce("firstAttemptAt",now()),"lockedUntil"=now()+interval '5 minutes' from picked where e.id=picked.id returning e.*;
end; $$;
revoke execute on function public.claim_email_batch() from public,anon,authenticated;
grant execute on function public.claim_email_batch() to service_role;

create function private.review_alert() returns trigger language plpgsql security definer set search_path = '' as $$
begin perform private.notify('newProductReview','New product review',new."productId"::text,'EDIT_PRODUCTS','/admin/reviews');return new;end; $$;
create trigger review_alert after insert on public.product_reviews for each row execute function private.review_alert();
create function private.refund_alert() returns trigger language plpgsql security definer set search_path = '' as $$
begin perform private.notify('refundRequest','Refund requested','Amount: NGN '||new.amount,'PROCESS_REFUNDS','/admin/returns');return new;end; $$;
create trigger refund_alert after insert on public.refunds for each row execute function private.refund_alert();
create function private.account_alert() returns trigger language plpgsql security definer set search_path = '' as $$
begin perform private.notify('newCustomer','New account registered',new.email,'VIEW_CUSTOMERS','/admin/customers');return new;end; $$;
create trigger account_alert after insert on public.profiles for each row execute function private.account_alert();

-- END 202610310011_email_notifications.sql


-- BEGIN 202610310012_realtime_catalogue.sql
-- Catalogue and content updates must reach other browsers, not just the editor.
-- This changes the publication only; existing RLS policies remain in effect.
do $$
declare target text;
begin
 if exists(select 1 from pg_publication where pubname='supabase_realtime') then
  foreach target in array array['product_categories','product_collections','product_collection_links','product_variants','product_reviews','discounts'] loop
   if to_regclass('public.'||target) is not null and not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename=target) then
    execute format('alter publication supabase_realtime add table public.%I',target);
   end if;
  end loop;
 end if;
end $$;

-- END 202610310012_realtime_catalogue.sql


